# ap-relay-client

A client library for connecting to an `ap-relay` WebSocket server.

## Overview

`ap-relay-client` provides `RelayProtocolClient` for connecting to a relay server, authenticating with cryptographic identities, and exchanging messages with other clients. It uses rustls for TLS.

## Quick Start

Add to your `Cargo.toml`:

```toml
[dependencies]
ap-relay-client = "0.1.0"
```

Basic client example:

```rust
use ap_relay_client::{RelayClientConfig, RelayProtocolClient, IncomingMessage};

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let config = RelayClientConfig {
        relay_url: "ws://localhost:8080".to_string(),
        identity_keypair: None, // Generates a new identity
    };

    let mut client = RelayProtocolClient::new(config);
    let mut incoming = client.connect().await?;

    println!("Connected! Fingerprint: {:?}", client.fingerprint());

    // Handle incoming messages
    tokio::spawn(async move {
        while let Some(msg) = incoming.recv().await {
            match msg {
                IncomingMessage::Send { source, payload, .. } => {
                    println!("Message from {:?}: {:?}", source, payload);
                }
                IncomingMessage::RendezvousInfo(code) => {
                    println!("Your pairing token: {}", code.as_str());
                }
                IncomingMessage::IdentityInfo { identity, .. } => {
                    println!("Found peer: {:?}", identity.fingerprint());
                }
            }
        }
    });

    // Request a pairing token for others to find you
    client.request_rendezvous().await?;

    Ok(())
}
```

"""In-memory storage implementations for UniFFI examples."""

from __future__ import annotations

from typing import Optional, List

from ap_uniffi import ConnectionStorage, FfiStoredConnection, IdentityStorage


class MemoryIdentityStorage(IdentityStorage):
    """In-memory identity storage — keypair lives only for the process lifetime."""

    def __init__(self):
        self._data = None

    def load_identity(self) -> bytes | None:
        return self._data

    def save_identity(self, identity_bytes: bytes):
        self._data = identity_bytes


class MemoryConnectionStorage(ConnectionStorage):
    """In-memory connection storage — connections live only for the process lifetime."""

    def __init__(self):
        self._connections: list[FfiStoredConnection] = []

    def get(self, fingerprint_hex: str) -> FfiStoredConnection | None:
        for c in self._connections:
            if c.fingerprint == fingerprint_hex:
                return c
        return None

    def save(self, connection: FfiStoredConnection):
        self._connections = [c for c in self._connections if c.fingerprint != connection.fingerprint]
        self._connections.append(connection)

    def update(self, fingerprint_hex: str, last_connected_at: int):
        for c in self._connections:
            if c.fingerprint == fingerprint_hex:
                c.last_connected_at = last_connected_at

    def list(self) -> list[FfiStoredConnection]:
        return list(self._connections)

//! End-to-end integration tests for WebSocket relay, pairing, and credential exchange
//!
//! These tests exercise the complete protocol stack using a real WebSocket relay server,
//! covering PSK and fingerprint-based pairing modes as well as credential exchange.

use std::net::SocketAddr;
use std::sync::Arc;

use ap_client::{
    ConnectionInfo, ConnectionStore, ConnectionUpdate, CredentialData, CredentialRequestReply,
    DefaultRelayClient, FingerprintVerificationReply, MemoryConnectionStore,
    MemoryIdentityProvider, PskToken, RemoteClient, RemoteClientHandle, RemoteClientNotification,
    UserClient, UserClientHandle, UserClientNotification, UserClientRequest,
};
use ap_relay::server::RelayServer;
use ap_relay_protocol::{IdentityFingerprint, IdentityKeyPair};
use tokio::time::{Duration, timeout};
use zeroize::Zeroizing;

// ============================================================================
// Test Infrastructure - Mock Implementations
// ============================================================================

// Uses MemoryIdentityProvider from the library instead of a local mock

/// Wrapper to share a MemoryConnectionStore via Arc<tokio::sync::Mutex>.
///
/// Needed by multi-device tests where multiple clients share the same connection store.
/// Uses tokio::sync::Mutex (whose MutexGuard is Send) to avoid Send issues in async trait methods.
struct SharedConnectionStore(Arc<tokio::sync::Mutex<MemoryConnectionStore>>);

#[async_trait::async_trait]
impl ConnectionStore for SharedConnectionStore {
    async fn get(&self, fingerprint: &IdentityFingerprint) -> Option<ConnectionInfo> {
        self.0.lock().await.get(fingerprint).await
    }

    async fn save(&mut self, connection: ConnectionInfo) -> Result<(), ap_client::ClientError> {
        self.0.lock().await.save(connection).await
    }

    async fn update(&mut self, update: ConnectionUpdate) -> Result<(), ap_client::ClientError> {
        self.0.lock().await.update(update).await
    }

    async fn list(&self) -> Vec<ConnectionInfo> {
        self.0.lock().await.list().await
    }
}

// ============================================================================
// Test Infrastructure - Helper Functions
// ============================================================================

/// Start a real relay server for testing and return its address
async fn start_test_server() -> SocketAddr {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .expect("should bind to localhost");
    let addr = listener.local_addr().expect("should get local address");

    let server = RelayServer::new(addr);
    tokio::spawn(async move { server.run_with_listener(listener).await.ok() });

    addr
}

/// Create a DefaultRelayClient connected to the given address
fn create_relay_client(addr: SocketAddr) -> DefaultRelayClient {
    DefaultRelayClient::from_url(format!("ws://{addr}"))
}

/// Create a test credential for use in tests
fn test_credential() -> CredentialData {
    CredentialData {
        username: Some("testuser".to_string()),
        password: [REDACTED]"testpassword123".to_string())),
        totp: Some("123456".to_string()),
        uri: Some("https://example.com".to_string()),
        notes: Some("Test credential notes".to_string()),
        credential_id: Some("test-item-id".to_string()),
        domain: Some("example.com".to_string()),
    }
}

// ============================================================================
// Test 1: PSK Pairing + Credential Exchange
// ============================================================================

#[tokio::test]
async fn test_e2e_psk_pairing_and_credential_request() {
    // 1. Start real relay server
    let addr = start_test_server().await;

    // 2. Create identities
    let user_identity = MemoryIdentityProvider::new();
    let remote_identity = MemoryIdentityProvider::new();

    // 3. Create UserClient with DefaultRelayClient
    let user_relay = create_relay_client(addr);
    let user_connection_store = MemoryConnectionStore::new();

    let UserClientHandle {
        client: user_client,
        notifications: mut notification_rx,
        requests: mut request_rx,
    } = UserClient::connect(
        Box::new(user_identity),
        Box::new(user_connection_store),
        Box::new(user_relay),
        None,
        None,
    )
    .await
    .expect("UserClient should connect");

    // 4. Get PSK token
    let token = user_client
        .get_psk_token(None, false)
        .await
        .expect("Should generate PSK token");

    // Parse token
    let (psk, fingerprint) = PskToken:[REDACTED]
        .expect("Should parse PSK token")
        .into_parts();

    // 5. Create RemoteClient with DefaultRelayClient
    let remote_relay = create_relay_client(addr);
    let remote_connection_store = MemoryConnectionStore::new();

    let RemoteClientHandle {
        client: remote_client,
        notifications: mut remote_notification_rx,
        requests: mut _remote_request_rx,
    } = RemoteClient::connect(
        Box::new(remote_identity),
        Box::new(remote_connection_store),
        Box::new(remote_relay),
    )
    .await
    .expect("RemoteClient should connect");

    // 8. Pair with PSK
    timeout(
        Duration::from_secs(10),
        remote_client.pair_with_psk(psk, fingerprint),
    )
    .await
    .expect("Pairing should not timeout")
    .expect("Pairing should succeed");

    // 9. Verify HandshakeComplete events on both sides
    let mut remote_handshake_complete = false;
    while let Ok(Some(event)) =
        timeout(Duration::from_millis(500), remote_notification_rx.recv()).await
    {
        if matches!(event, RemoteClientNotification::HandshakeComplete) {
            remote_handshake_complete = true;
            break;
        }
    }
    assert!(
        remote_handshake_complete,
        "RemoteClient should emit HandshakeComplete"
    );

    // Drain user notifications to find HandshakeComplete
    let mut user_handshake_complete = false;
    while let Ok(Some(event)) = timeout(Duration::from_millis(500), notification_rx.recv()).await {
        if matches!(event, UserClientNotification::HandshakeComplete {}) {
            user_handshake_complete = true;
            break;
        }
    }
    assert!(
        user_handshake_complete,
        "UserClient should emit HandshakeComplete"
    );

    // 10. Spawn credential response handler for UserClient
    let credential_handler = tokio::spawn(async move {
        while let Some(request) = request_rx.recv().await {
            if let UserClientRequest::CredentialRequest { query, reply, .. } = request {
                let domain = match &query {
                    ap_client::CredentialQuery::Domain(d) => d.clone(),
                    _ => panic!("expected Domain query"),
                };
                assert_eq!(domain, "example.com", "Domain should match request");
                let _ = reply.send(CredentialRequestReply {
                    approved: true,
                    credential: Some(test_credential()),
                    credential_id: Some("test-item-id".to_string()),
                });
                break;
            }
        }
    });

    // 12. RemoteClient requests credential
    let credential = timeout(
        Duration::from_secs(10),
        remote_client.request_credential(
            &ap_client::CredentialQuery::Domain("example.com".to_string()),
            None,
        ),
    )
    .await
    .expect("Credential request should not timeout")
    .expect("Credential request should succeed");

    // 13. Verify credential contents
    assert_eq!(credential.username, Some("testuser".to_string()));
    assert_eq!(
        credential.password,
        Some(Zeroizing::new("testpassword123".to_string()))
    );
    assert_eq!(credential.totp, Some("123456".to_string()));
    assert_eq!(credential.uri, Some("https://example.com".to_string()));
    assert_eq!(credential.notes, Some("Test credential notes".to_string()));

    // Cleanup
    credential_handler.abort();
    drop(remote_client);
    drop(user_client);
}

// ============================================================================
// Test 2: Fingerprint Pairing + Credential Exchange
// ============================================================================

#[tokio::test]
async fn test_e2e_fingerprint_pairing_and_credential_request() {
    // 1. Start real relay server
    let addr = start_test_server().await;

    // 2. Create identities
    let user_identity = MemoryIdentityProvider::new();
    let remote_identity = MemoryIdentityProvider::new();

    // 3. Create UserClient with DefaultRelayClient
    let user_relay = create_relay_client(addr);
    let user_connection_store = MemoryConnectionStore::new();

    let UserClientHandle {
        client: user_client,
        notifications: _notification_rx,
        requests: mut request_rx,
    } = UserClient::connect(
        Box::new(user_identity),
        Box::new(user_connection_store),
        Box::new(user_relay),
        None,
        None,
    )
    .await
    .expect("UserClient should connect");

    // 4. Get rendezvous token
    let code = user_client
        .get_rendezvous_token(None)
        .await
        .expect("Should get rendezvous token");
    let code = code.as_str().to_string();

    // 5. Create RemoteClient with DefaultRelayClient
    let remote_relay = create_relay_client(addr);
    let remote_connection_store = MemoryConnectionStore::new();

    let RemoteClientHandle {
        client: remote_client,
        notifications: mut remote_notification_rx,
        requests: mut _remote_request_rx,
    } = RemoteClient::connect(
        Box::new(remote_identity),
        Box::new(remote_connection_store),
        Box::new(remote_relay),
    )
    .await
    .expect("RemoteClient should connect");

    // 8. Spawn approval handler for VerifyFingerprint request on USER side (listener must verify)
    let user_approval_task = tokio::spawn(async move {
        while let Some(request) = request_rx.recv().await {
            if let UserClientRequest::VerifyFingerprint { reply, .. } = request {
                // Auto-approve the fingerprint on the user/listener side
                let _ = reply.send(FingerprintVerificationReply {
                    approved: true,
                    name: None,
                });
                break;
            }
        }
        request_rx
    });

    // 9. Pair with handshake using rendezvous code (verify_fingerprint=false on remote side)
    let paired_fingerprint = timeout(
        Duration::from_secs(15),
        remote_client.pair_with_handshake(code, false),
    )
    .await
    .expect("Pairing should not timeout")
    .expect("Pairing should succeed");

    // 10. Verify HandshakeFingerprint was emitted on remote side (informational)
    let mut got_fingerprint = false;
    while let Ok(Some(event)) =
        timeout(Duration::from_millis(500), remote_notification_rx.recv()).await
    {
        if matches!(event, RemoteClientNotification::HandshakeFingerprint { .. }) {
            got_fingerprint = true;
            break;
        }
    }
    assert!(
        got_fingerprint,
        "RemoteClient should emit HandshakeFingerprint (informational)"
    );

    // 11. Verify connection is cached
    assert!(
        remote_client
            .has_connection(paired_fingerprint)
            .await
            .expect("has_connection should not fail"),
        "Connection should be cached in RemoteClient's connection store"
    );

    // 12. Spawn credential response handler for UserClient
    let mut request_rx = user_approval_task
        .await
        .expect("User approval task should complete");
    let credential_handler = tokio::spawn(async move {
        while let Some(request) = request_rx.recv().await {
            if let UserClientRequest::CredentialRequest { query, reply, .. } = request {
                let domain = match &query {
                    ap_client::CredentialQuery::Domain(d) => d.clone(),
                    _ => panic!("expected Domain query"),
                };
                assert_eq!(domain, "example.com", "Domain should match request");
                let _ = reply.send(CredentialRequestReply {
                    approved: true,
                    credential: Some(test_credential()),
                    credential_id: Some("test-item-id".to_string()),
                });
                break;
            }
        }
    });

    // 14. RemoteClient requests credential
    let credential = timeout(
        Duration::from_secs(10),
        remote_client.request_credential(
            &ap_client::CredentialQuery::Domain("example.com".to_string()),
            None,
        ),
    )
    .await
    .expect("Credential request should not timeout")
    .expect("Credential request should succeed");

    // 15. Verify credential contents
    assert_eq!(credential.username, Some("testuser".to_string()));
    assert_eq!(
        credential.password,
        Some(Zeroizing::new("testpassword123".to_string()))
    );

    // Cleanup
    credential_handler.abort();
    drop(remote_client);
    drop(user_client);
}

// ============================================================================
// Test 3: Credential Request Denied
// ============================================================================

#[tokio::test]
async fn test_e2e_credential_request_denied() {
    // 1. Start real relay server
    let addr = start_test_server().await;

    // 2. Create identities
    let user_identity = MemoryIdentityProvider::new();
    let remote_identity = MemoryIdentityProvider::new();

    // 3. Create UserClient with DefaultRelayClient
    let user_relay = create_relay_client(addr);
    let user_connection_store = MemoryConnectionStore::new();

    let UserClientHandle {
        client: user_client,
        notifications: mut notification_rx,
        requests: mut request_rx,
    } = UserClient::connect(
        Box::new(user_identity),
        Box::new(user_connection_store),
        Box::new(user_relay),
        None,
        None,
    )
    .await
    .expect("UserClient should connect");

    // 4. Get PSK token
    let token = user_client
        .get_psk_token(None, false)
        .await
        .expect("Should generate PSK token");

    // Parse token
    let (psk, fingerprint) = PskToken:[REDACTED]
        .expect("Should parse PSK token")
        .into_parts();

    // 5. Create RemoteClient
    let remote_relay = create_relay_client(addr);
    let remote_connection_store = MemoryConnectionStore::new();

    let RemoteClientHandle {
        client: remote_client,
        notifications: _remote_notification_rx,
        requests: mut _remote_request_rx,
    } = RemoteClient::connect(
        Box::new(remote_identity),
        Box::new(remote_connection_store),
        Box::new(remote_relay),
    )
    .await
    .expect("RemoteClient should connect");

    // 7. Pair with PSK
    timeout(
        Duration::from_secs(10),
        remote_client.pair_with_psk(psk, fingerprint),
    )
    .await
    .expect("Pairing should not timeout")
    .expect("Pairing should succeed");

    // Drain notifications to ensure handshake is complete
    while let Ok(Some(_)) = timeout(Duration::from_millis(500), notification_rx.recv()).await {}

    // 8. Spawn credential DENIAL handler for UserClient
    let denial_handler = tokio::spawn(async move {
        while let Some(request) = request_rx.recv().await {
            if let UserClientRequest::CredentialRequest { query, reply, .. } = request {
                assert!(
                    matches!(&query, ap_client::CredentialQuery::Domain(d) if d == "example.com")
                );
                // Deny the credential request
                let _ = reply.send(CredentialRequestReply {
                    approved: false,
                    credential: None,
                    credential_id: None,
                });
                break;
            }
        }
    });

    // 9. RemoteClient requests credential - should fail
    let result = timeout(
        Duration::from_secs(10),
        remote_client.request_credential(
            &ap_client::CredentialQuery::Domain("example.com".to_string()),
            None,
        ),
    )
    .await
    .expect("Credential request should not timeout");

    // 10. Verify the request was denied
    assert!(result.is_err(), "Credential request should be denied");

    // Cleanup
    denial_handler.abort();
    drop(remote_client);
    drop(user_client);
}

// ============================================================================
// Test 4: Multiple Sequential Credential Requests
// ============================================================================

#[tokio::test]
async fn test_e2e_multiple_credential_requests() {
    // 1. Start real relay server
    let addr = start_test_server().await;

    // 2. Create identities
    let user_identity = MemoryIdentityProvider::new();
    let remote_identity = MemoryIdentityProvider::new();

    // 3. Create UserClient with DefaultRelayClient
    let user_relay = create_relay_client(addr);
    let user_connection_store = MemoryConnectionStore::new();

    let UserClientHandle {
        client: user_client,
        notifications: mut notification_rx,
        requests: mut request_rx,
    } = UserClient::connect(
        Box::new(user_identity),
        Box::new(user_connection_store),
        Box::new(user_relay),
        None,
        None,
    )
    .await
    .expect("UserClient should connect");

    // 4. Get PSK token
    let token = user_client
        .get_psk_token(None, false)
        .await
        .expect("Should generate PSK token");

    // Parse token
    let (psk, fingerprint) = PskToken:[REDACTED]
        .expect("Should parse PSK token")
        .into_parts();

    // 5. Create RemoteClient
    let remote_relay = create_relay_client(addr);
    let remote_connection_store = MemoryConnectionStore::new();

    let RemoteClientHandle {
        client: remote_client,
        notifications: _remote_notification_rx,
        requests: mut _remote_request_rx,
    } = RemoteClient::connect(
        Box::new(remote_identity),
        Box::new(remote_connection_store),
        Box::new(remote_relay),
    )
    .await
    .expect("RemoteClient should connect");

    // 7. Pair with PSK
    timeout(
        Duration::from_secs(10),
        remote_client.pair_with_psk(psk, fingerprint),
    )
    .await
    .expect("Pairing should not timeout")
    .expect("Pairing should succeed");

    // Drain notifications to ensure handshake is complete
    while let Ok(Some(_)) = timeout(Duration::from_millis(500), notification_rx.recv()).await {}

    // 8. Spawn credential response handler that handles multiple requests
    let credential_handler = tokio::spawn(async move {
        let mut request_count = 0;
        while let Some(request) = request_rx.recv().await {
            if let UserClientRequest::CredentialRequest { query, reply, .. } = request {
                let domain = match &query {
                    ap_client::CredentialQuery::Domain(d) => d.clone(),
                    _ => panic!("expected Domain query"),
                };
                request_count += 1;

                // Create credential with domain-specific data
                let credential = CredentialData {
                    username: Some(format!("user_{domain}")),
                    password: [REDACTED]"pass_{domain}"))),
                    totp: None,
                    uri: Some(format!("https://{domain}")),
                    notes: Some(format!("Request #{request_count}")),
                    credential_id: None,
                    domain: Some(domain.clone()),
                };

                let _ = reply.send(CredentialRequestReply {
                    approved: true,
                    credential: Some(credential),
                    credential_id: None,
                });

                if request_count >= 3 {
                    break;
                }
            }
        }
    });

    // 9. Make 3 sequential credential requests
    let domains = ["example.com", "test.org", "demo.net"];

    for domain in &domains {
        let credential = timeout(
            Duration::from_secs(10),
            remote_client.request_credential(
                &ap_client::CredentialQuery::Domain(domain.to_string()),
                None,
            ),
        )
        .await
        .expect("Credential request should not timeout")
        .expect("Credential request should succeed");

        // Verify domain-specific credential
        assert_eq!(credential.username, Some(format!("user_{domain}")));
        assert_eq!(
            credential.password,
            Some(Zeroizing::new(format!("pass_{domain}")))
        );
        assert_eq!(credential.uri, Some(format!("https://{domain}")));
    }

    // Cleanup
    credential_handler.abort();
    drop(remote_client);
    drop(user_client);
}

// ============================================================================
// Test 5: Transport State Persistence
// ============================================================================

#[tokio::test]
async fn test_e2e_transport_state_persistence() {
    // 1. Start real relay server
    let addr = start_test_server().await;

    // 2. Create identities
    let user_identity = MemoryIdentityProvider::new();
    let remote_identity = MemoryIdentityProvider::new();

    // 3. Create UserClient with DefaultRelayClient
    let user_relay = create_relay_client(addr);
    let user_connection_store = MemoryConnectionStore::new();

    let UserClientHandle {
        client: user_client,
        notifications: mut notification_rx,
        requests: _request_rx,
    } = UserClient::connect(
        Box::new(user_identity),
        Box::new(user_connection_store),
        Box::new(user_relay),
        None,
        None,
    )
    .await
    .expect("UserClient should connect");

    // 4. Get PSK token
    let token = user_client
        .get_psk_token(None, false)
        .await
        .expect("Should generate PSK token");

    // Parse token: format is <psk_hex>_<fingerprint_hex>
    let (psk, fingerprint) = PskToken:[REDACTED]
        .expect("Should parse PSK token")
        .into_parts();

    // 5. Create RemoteClient with shared connection store for later access
    let remote_relay = create_relay_client(addr);
    let remote_connection_store = Arc::new(tokio::sync::Mutex::new(MemoryConnectionStore::new()));
    let connection_store_clone = Arc::clone(&remote_connection_store);

    // Reuse the module-level SharedConnectionStore wrapper
    let RemoteClientHandle {
        client: remote_client,
        notifications: mut remote_notification_rx,
        requests: mut _remote_request_rx,
    } = RemoteClient::connect(
        Box::new(remote_identity),
        Box::new(SharedConnectionStore(remote_connection_store)),
        Box::new(remote_relay),
    )
    .await
    .expect("RemoteClient should connect");

    // 8. Pair with PSK
    timeout(
        Duration::from_secs(10),
        remote_client.pair_with_psk(psk, fingerprint),
    )
    .await
    .expect("Pairing should not timeout")
    .expect("Pairing should succeed");

    // 9. Verify HandshakeComplete events on both sides
    let mut remote_handshake_complete = false;
    while let Ok(Some(event)) =
        timeout(Duration::from_millis(500), remote_notification_rx.recv()).await
    {
        if matches!(event, RemoteClientNotification::HandshakeComplete) {
            remote_handshake_complete = true;
            break;
        }
    }
    assert!(
        remote_handshake_complete,
        "RemoteClient should emit HandshakeComplete"
    );

    // Drain user notifications to find HandshakeComplete
    let mut user_handshake_complete = false;
    while let Ok(Some(event)) = timeout(Duration::from_millis(500), notification_rx.recv()).await {
        if matches!(event, UserClientNotification::HandshakeComplete {}) {
            user_handshake_complete = true;
            break;
        }
    }
    assert!(
        user_handshake_complete,
        "UserClient should emit HandshakeComplete"
    );

    // 10. Load connection from connection store and verify transport state was saved
    let connection = connection_store_clone
        .lock()
        .await
        .get(&fingerprint)
        .await
        .expect("Connection should exist in store");

    // 11. Assert the transport state is Some
    assert!(
        connection.transport_state.is_some(),
        "Transport state should be saved after pairing"
    );
    let mut restored_transport = connection
        .transport_state
        .expect("Transport state should be present");

    // 12. Verify the restored transport can encrypt (proving it's a valid transport)
    let test_message = b"test message for persistence verification";
    let encrypted = restored_transport
        .encrypt(test_message)
        .expect("Restored transport should encrypt");
    // Encode to wire format to verify the packet is valid and non-empty
    let encoded = encrypted.encode();
    assert!(
        !encoded.is_empty(),
        "Encrypted packet should encode to non-empty bytes"
    );

    // Cleanup
    drop(remote_client);
    drop(user_client);
}

