// Test 6: Multi-Device Credential Response
// ============================================================================

#[tokio::test]
async fn test_e2e_multi_device_credential_response() {
    // 1. Start real relay server
    let addr = start_test_server().await;

    // 2. Create identities - same user identity for both devices
    let user_keypair = IdentityKeyPair::generate();
    let user_keypair_device2 = user_keypair.clone();

    // 3. Create UserClient Device 1 with DefaultRelayClient
    let user_relay1 = create_relay_client(addr);

    // Use Arc for shared access between multiple UserClient devices
    let user_connection_store1 = Arc::new(tokio::sync::Mutex::new(MemoryConnectionStore::new()));
    let connection_store_clone = Arc::clone(&user_connection_store1);

    let UserClientHandle {
        client: user_client1,
        notifications: mut notification_rx1,
        requests: mut request_rx1,
    } = UserClient::connect(
        Box::new(MemoryIdentityProvider::from_keypair(user_keypair)),
        Box::new(SharedConnectionStore(Arc::clone(&user_connection_store1))),
        Box::new(user_relay1),
        None,
        None,
    )
    .await
    .expect("UserClient Device 1 should connect");

    // 5. Get PSK token
    let token = [REDACTED]
        .get_psk_token(None, false)
        .await
        .expect("Should generate PSK token");

    // Parse token
    let (psk, user_fingerprint) = PskToken:[REDACTED]
        .expect("Should parse PSK token")
        .into_parts();

    // 6. Create RemoteClient
    let remote_relay = create_relay_client(addr);
    let RemoteClientHandle {
        client: remote_client,
        notifications: mut remote_notification_rx,
        requests: mut _remote_request_rx,
    } = RemoteClient::connect(
        Box::new(MemoryIdentityProvider::new()),
        Box::new(MemoryConnectionStore::new()),
        Box::new(remote_relay),
    )
    .await
    .expect("RemoteClient should connect");

    // 7. Pair with PSK
    timeout(
        Duration::from_secs(10),
        remote_client.pair_with_psk(psk, user_fingerprint),
    )
    .await
    .expect("Pairing should not timeout")
    .expect("Pairing should succeed");

    // 8. Wait for handshake complete on both sides
    while let Ok(Some(event)) =
        timeout(Duration::from_millis(500), remote_notification_rx.recv()).await
    {
        if matches!(event, RemoteClientNotification::HandshakeComplete) {
            break;
        }
    }
    while let Ok(Some(event)) = timeout(Duration::from_millis(500), notification_rx1.recv()).await {
        if matches!(event, UserClientNotification::HandshakeComplete {}) {
            break;
        }
    }

    // 9. Create UserClient Device 2 with SHARED connection store
    let user_relay2 = create_relay_client(addr);
    let UserClientHandle {
        client: user_client2,
        notifications: mut notification_rx2,
        requests: mut request_rx2,
    } = UserClient::connect(
        Box::new(MemoryIdentityProvider::from_keypair(user_keypair_device2)),
        Box::new(SharedConnectionStore(Arc::clone(&connection_store_clone))),
        Box::new(user_relay2),
        None,
        None,
    )
    .await
    .expect("UserClient Device 2 should connect");

    // Wait for Device 2 to be listening
    timeout(Duration::from_secs(2), async {
        loop {
            if let Some(UserClientNotification::Listening {}) = notification_rx2.recv().await {
                break;
            }
        }
    })
    .await
    .expect("Device 2 should listen");

    // 10. Spawn response handlers for both devices.
    // Both handlers always approve. Since the relay broadcasts credential
    // requests to all connections with the same identity, both devices
    // receive every request. Each device independently responds via its
    // own oneshot. The remote client uses the first response that arrives.
    let handler1 = tokio::spawn(async move {
        while let Some(request) = request_rx1.recv().await {
            if let UserClientRequest::CredentialRequest { reply, .. } = request {
                let _ = reply.send(CredentialRequestReply {
                    approved: true,
                    credential: Some(CredentialData {
                        username: Some("device1_user".into()),
                        password: [REDACTED]"device1_pass".into())),
                        totp: None,
                        uri: None,
                        notes: None,
                        credential_id: None,
                        domain: Some("example.com".into()),
                    }),
                    credential_id: None,
                });
            }
        }
    });

    let handler2 = tokio::spawn(async move {
        while let Some(request) = request_rx2.recv().await {
            if let UserClientRequest::CredentialRequest { reply, .. } = request {
                let _ = reply.send(CredentialRequestReply {
                    approved: true,
                    credential: Some(CredentialData {
                        username: Some("device2_user".into()),
                        password: [REDACTED]"device2_pass".into())),
                        totp: None,
                        uri: None,
                        notes: None,
                        credential_id: None,
                        domain: Some("example.com".into()),
                    }),
                    credential_id: None,
                });
            }
        }
    });

    // 11. Request 100 credentials and track which device responds
    let mut device1_count = 0;
    let mut device2_count = 0;

    for _ in 0..100 {
        let credential = timeout(
            Duration::from_secs(10),
            remote_client.request_credential(
                &ap_client::CredentialQuery::Domain("example.com".to_string()),
                None,
            ),
        )
        .await
        .expect("Should not timeout")
        .expect("Should succeed");

        if credential.username == Some("device1_user".into()) {
            device1_count += 1;
        } else if credential.username == Some("device2_user".into()) {
            device2_count += 1;
        }
    }

    // 12. Verify responses were received from at least one device.
    // Both devices handle all requests (proving transport state sharing
    // works), but the remote client uses whichever response arrives first.
    // In practice one device may win all races, so we only assert totals.
    assert_eq!(
        device1_count + device2_count,
        100,
        "Total should be 100 responses"
    );
    println!(
        "Device 1 handled {} requests, Device 2 handled {} requests",
        device1_count, device2_count
    );

    // Cleanup
    handler1.abort();
    handler2.abort();
    drop(remote_client);
    drop(user_client1);
    drop(user_client2);
}

use ap_relay::server::RelayServer;
use ap_relay_client::{IdentityKeyPair, IncomingMessage, RelayProtocolClient};
use std::net::SocketAddr;

/// Small delay to allow the server to finish registering a connection after
/// the client's `connect()` returns. The server doesn't send an auth
/// confirmation, so there's a brief window where the client considers itself
/// authenticated but the server hasn't inserted it into the connection map yet.
const POST_CONNECT_DELAY: tokio::time::Duration = tokio::time::Duration::from_millis(50);

async fn start_test_server() -> SocketAddr {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .expect("should bind to localhost");
    let addr = listener.local_addr().expect("should get local address");

    let server = RelayServer::new(addr);
    tokio::spawn(async move { server.run_with_listener(listener).await.ok() });

    addr
}

#[tokio::test]
async fn test_client_connect_and_authenticate() {
    let addr = start_test_server().await;

    let mut client = RelayProtocolClient::from_url(format!("ws://{addr}"));
    let _incoming = client
        .connect(IdentityKeyPair::generate())
        .await
        .expect("should connect");

    assert!(client.is_authenticated().await);

    // Verify fingerprint is set
    let fingerprint = client.fingerprint();
    assert_ne!(fingerprint.0, [0u8; 32]);

    client.disconnect().await.expect("should disconnect");
}

#[tokio::test]
async fn test_two_clients_messaging() {
    let addr = start_test_server().await;

    let mut client_a = RelayProtocolClient::from_url(format!("ws://{addr}"));
    let mut client_b = RelayProtocolClient::from_url(format!("ws://{addr}"));

    let mut incoming_a = client_a
        .connect(IdentityKeyPair::generate())
        .await
        .expect("client A should connect");
    let mut incoming_b = client_b
        .connect(IdentityKeyPair::generate())
        .await
        .expect("client B should connect");
    tokio::time::sleep(POST_CONNECT_DELAY).await;

    let fingerprint_a = client_a.fingerprint();
    let fingerprint_b = client_b.fingerprint();

    // A sends to B
    let payload = b"Hello from A".to_vec();
    client_a
        .send_to(fingerprint_b, payload.clone())
        .await
        .expect("client A should send message");

    // B receives message
    tokio::time::timeout(tokio::time::Duration::from_secs(5), async {
        let msg = incoming_b
            .recv()
            .await
            .expect("client B should receive message");
        match msg {
            IncomingMessage::Send {
                source,
                payload: recv_payload,
                ..
            } => {
                assert_eq!(source, fingerprint_a);
                assert_eq!(recv_payload, payload);
            }
            _ => panic!("Expected Send message"),
        }
    })
    .await
    .expect("receive should not timeout");

    // B sends to A
    let payload_b = b"Hello from B".to_vec();
    client_b
        .send_to(fingerprint_a, payload_b.clone())
        .await
        .expect("client B should send message");

    // A receives message
    tokio::time::timeout(tokio::time::Duration::from_secs(5), async {
        let msg = incoming_a
            .recv()
            .await
            .expect("client A should receive message");
        match msg {
            IncomingMessage::Send {
                source,
                payload: recv_payload,
                ..
            } => {
                assert_eq!(source, fingerprint_b);
                assert_eq!(recv_payload, payload_b);
            }
            _ => panic!("Expected Send message"),
        }
    })
    .await
    .expect("receive should not timeout");

    client_a
        .disconnect()
        .await
        .expect("client A should disconnect");
    client_b
        .disconnect()
        .await
        .expect("client B should disconnect");
}

