//! Thin WASM wrapper around `RemoteClient`.
//!
//! Exposes individual `RemoteClient` methods to JavaScript. Connection
//! mode orchestration (PSK vs rendezvous vs cached) lives in the JS
//! `AgentAccessClient` class, not here.

use ap_client::{IdentityFingerprint, PskToken, RemoteClient};
use wasm_bindgen::prelude::*;

use crate::relay_client::WasmRelayClient;
use crate::storage::{LocalStorageConnectionStore, LocalStorageIdentityProvider};
use crate::types::{client_error_to_js, JsCredentialData};

/// An Agent Access Remote Client for the browser.
///
/// Usage from JavaScript:
/// ```js
/// const client = new WasmRemoteClient("wss://ap.lesspassword.dev", "js-remote");
/// await client.connect();
/// const fp = await client.pairWithHandshake("ABC-DEF-GHI");
/// const cred = await client.requestCredential("example.com");
/// console.log(cred.username, cred.password);
/// client.close();
/// ```
#[wasm_bindgen]
pub struct WasmRemoteClient {
    inner: Option<RemoteClient>,
    relay_url: String,
    identity_name: String,
}

#[wasm_bindgen]
impl WasmRemoteClient {
    /// Create a new client.
    ///
    /// @param relay_url - WebSocket URL of the relay server
    /// @param identity_name - Name for the identity keypair stored in localStorage
    #[wasm_bindgen(constructor)]
    pub fn new(relay_url: &str, identity_name: &str) -> Self {
        Self {
            inner: None,
            relay_url: relay_url.to_string(),
            identity_name: identity_name.to_string(),
        }
    }

    /// Connect to the relay server.
    ///
    /// Establishes the WebSocket connection and authenticates. After this,
    /// call one of the pairing methods to establish a secure channel.
    pub async fn connect(&mut self) -> Result<(), JsValue> {
        let identity = LocalStorageIdentityProvider::load_or_generate(&self.identity_name)
            .map_err(client_error_to_js)?;

        let connection_store = LocalStorageConnectionStore::load_or_create(&self.identity_name)
            .map_err(client_error_to_js)?;

        let relay_client = Box::new(WasmRelayClient::new(self.relay_url.clone()));

        let handle = RemoteClient::connect(
            Box::new(identity),
            Box::new(connection_store),
            relay_client,
        )
        .await
        .map_err(client_error_to_js)?;

        self.inner = Some(handle.client);
        // Drop notification receiver — not used in this example.
        // Dropping is safe: the event loop ignores send failures.
        drop(handle.notifications);

        Ok(())
    }

    /// Pair with a new device using a rendezvous code.
    ///
    /// @param code - Rendezvous code (e.g. "ABC-DEF-GHI")
    /// @returns The 6-char handshake fingerprint as a hex string
    #[wasm_bindgen(js_name = "pairWithHandshake")]
    pub async fn pair_with_handshake(&self, code: String) -> Result<String, JsValue> {
        let client = self
            .inner
            .as_ref()
            .ok_or_else(|| JsValue::from_str("Not connected — call connect() first"))?;

        let fp = client
            .pair_with_handshake(code, false)
            .await
            .map_err(client_error_to_js)?;

        Ok(hex::encode(fp.0))
    }

    /// Pair with a new device using a PSK token.
    ///
    /// @param psk_token - PSK token string (<64-hex-psk>_<64-hex-fingerprint>)
    #[wasm_bindgen(js_name = "pairWithPsk")]
    pub async fn pair_with_psk(&self, psk_token: String) -> Result<(), JsValue> {
        let client = self
            .inner
            .as_ref()
            .ok_or_else(|| JsValue::from_str("Not connected — call connect() first"))?;

        let parsed = PskToken:[REDACTED]
            .map_err(|e| JsValue::from_str(&format!("Invalid PSK token: {e}")))?;
        let (psk, fingerprint) = parsed.into_parts();

        client
            .pair_with_psk(psk, fingerprint)
            .await
            .map_err(client_error_to_js)?;

        Ok(())
    }

    /// Reconnect to a previously paired device using a cached session.
    ///
    /// @param fingerprint_hex - Hex-encoded identity fingerprint
    #[wasm_bindgen(js_name = "loadCachedConnection")]
    pub async fn load_cached_connection(&self, fingerprint_hex: String) -> Result<(), JsValue> {
        let client = self
            .inner
            .as_ref()
            .ok_or_else(|| JsValue::from_str("Not connected — call connect() first"))?;

        let fingerprint = IdentityFingerprint::from_hex(&fingerprint_hex)
            .map_err(|e| JsValue::from_str(&format!("Invalid fingerprint: {e}")))?;

        client
            .load_cached_connection(fingerprint)
            .await
            .map_err(client_error_to_js)?;

        Ok(())
    }

    /// Request a credential for a domain.
    ///
    /// @param domain - The domain to look up (e.g. "example.com")
    /// @returns CredentialData with username, password, totp, etc.
    #[wasm_bindgen(js_name = "requestCredential")]
    pub async fn request_credential(&self, domain: &str) -> Result<JsCredentialData, JsValue> {
        let client = self
            .inner
            .as_ref()
            .ok_or_else(|| JsValue::from_str("Not connected — call connect() first"))?;

        let query = ap_client::CredentialQuery::Domain(domain.to_string());
        let cred = client
            .request_credential(&query, None)
            .await
            .map_err(client_error_to_js)?;

        Ok(JsCredentialData::from(cred))
    }

    /// Close the connection and release resources.
    pub fn close(&mut self) {
        self.inner.take();
    }

}

//! Browser WebSocket implementation of the `RelayClient` trait.
//!
//! Uses `web_sys::WebSocket` to communicate with the relay server,
//! bridging the browser's callback-driven API to the channel-based
//! `RelayClient` trait.

use ap_client::error::ClientError;
use ap_client::RelayClient;
use ap_relay_client::IncomingMessage;
use ap_relay_protocol::{IdentityFingerprint, IdentityKeyPair, Messages, RendezvousCode};
use async_trait::async_trait;
use std::sync::{Arc, Mutex};
use tokio::sync::{mpsc, oneshot};
use wasm_bindgen::closure::Closure;
use wasm_bindgen::prelude::*;
use web_sys::{CloseEvent, ErrorEvent, MessageEvent, WebSocket};

/// A `RelayClient` implementation using the browser's WebSocket API.
///
/// Closures are registered with `.forget()` (standard WASM practice for event
/// handlers). The struct only holds `Send + Sync` types.
pub struct WasmRelayClient {
    url: String,
    ws: Option<WebSocket>,
}

impl WasmRelayClient {
    pub fn new(url: String) -> Self {
        Self { url, ws: None }
    }

    fn send_json(&self, msg: &Messages) -> Result<(), ClientError> {
        let ws = self
            .ws
            .as_ref()
            .ok_or_else(|| ClientError::ConnectionFailed("Not connected".to_string()))?;
        let json = serde_json::to_string(msg)
            .map_err(|e| ClientError::ConnectionFailed(format!("Serialization error: {e}")))?;
        ws.send_with_str(&json)
            .map_err(|e| ClientError::ConnectionFailed(format!("WebSocket send error: {e:?}")))?;
        Ok(())
    }
}

#[async_trait]
impl RelayClient for WasmRelayClient {
    async fn connect(
        &mut self,
        identity: IdentityKeyPair,
    ) -> Result<mpsc::UnboundedReceiver<IncomingMessage>, ClientError> {
        let ws = WebSocket::new(&self.url).map_err(|e| {
            ClientError::ConnectionFailed(format!("Failed to create WebSocket: {e:?}"))
        })?;

        // Channels for signaling connection open and auth completion
        let (open_tx, open_rx) = oneshot::channel::<Result<(), ClientError>>();
        let (auth_tx, auth_rx) = oneshot::channel::<Result<(), ClientError>>();
        let (incoming_tx, incoming_rx) = mpsc::unbounded_channel::<IncomingMessage>();

        // Arc<Mutex<Option>> so closures are Send and can take the sender once.
        // std::sync::Mutex (not tokio) because these are captured in synchronous JS callbacks.
        let open_tx = Arc::new(Mutex::new(Some(open_tx)));
        let auth_tx = Arc::new(Mutex::new(Some(auth_tx)));

        {
            let open_tx = Arc::clone(&open_tx);
            let cb = Closure::once(move |_: JsValue| {
                if let Some(tx) = open_tx
                    .lock()
                    .expect("open_tx lock poisoned")
                    .take()
                {
                    let _ = tx.send(Ok(()));
                }
            });
            ws.set_onopen(Some(cb.as_ref().unchecked_ref()));
            cb.forget();
        }

        // onerror before open — signals connection failure
        {
            let open_tx = Arc::clone(&open_tx);
            let cb = Closure::once(move |_: ErrorEvent| {
                if let Some(tx) = open_tx
                    .lock()
                    .expect("open_tx err lock poisoned")
                    .take()
                {
                    let _ = tx.send(Err(ClientError::ConnectionFailed(
                        "WebSocket connection error".to_string(),
                    )));
                }
            });
            ws.set_onerror(Some(cb.as_ref().unchecked_ref()));
            cb.forget();
        }

        open_rx
            .await
            .map_err(|_| ClientError::ConnectionFailed("Open channel dropped".to_string()))?
            .map_err(|e| ClientError::ConnectionFailed(e.to_string()))?;

        // Clear oneshot handlers now that the connection is open
        ws.set_onopen(None);
        ws.set_onerror(None);
        {
            let ws_clone = ws.clone();
            let auth_tx = Arc::clone(&auth_tx);
            let auth_done = Arc::new(Mutex::new(false));

            let cb = Closure::wrap(Box::new(move |event: MessageEvent| {
                let text = match event.data().as_string() {
                    Some(t) => t,
                    None => return,
                };

                let parsed: Messages = match serde_json::from_str(&text) {
                    Ok(m) => m,
                    Err(e) => {
                        tracing::warn!("Failed to parse relay message: {e}");
                        return;
                    }
                };

                let is_auth_done =
                    *auth_done.lock().expect("auth_done lock poisoned");
                if !is_auth_done {
                    match parsed {
                        Messages::AuthChallenge(challenge) => {
                            let response = challenge.sign(&identity);
                            let auth_msg =
                                Messages::AuthResponse(identity.identity(), response);
                            match serde_json::to_string(&auth_msg) {
                                Ok(json) => {
                                    if let Err(e) = ws_clone.send_with_str(&json) {
                                        tracing::error!("Failed to send auth response: {e:?}");
                                        if let Some(tx) = auth_tx
                                            .lock()
                                            .expect("auth_tx lock")
                                            .take()
                                        {
                                            let _ = tx.send(Err(ClientError::ConnectionFailed(
                                                "Failed to send auth response".to_string(),
                                            )));
                                        }
                                        return;
                                    }
                                    *auth_done
                                        .lock()
                                        .expect("auth_done lock") = true;
                                    if let Some(tx) = auth_tx
                                        .lock()
                                        .expect("auth_tx lock")
                                        .take()
                                    {
                                        let _ = tx.send(Ok(()));
                                    }
                                }
                                Err(e) => {
                                    if let Some(tx) = auth_tx
                                        .lock()
                                        .expect("auth_tx lock")
                                        .take()
                                    {
                                        let _ = tx.send(Err(ClientError::ConnectionFailed(
                                            format!("Auth serialization error: {e}"),
                                        )));
                                    }
                                }
                            }
                        }
                        _ => {
                            tracing::warn!("Expected AuthChallenge, got: {parsed:?}");
                            if let Some(tx) = auth_tx
                                .lock()
                                .expect("auth_tx lock")
                                .take()
                            {
                                let _ = tx.send(Err(ClientError::ConnectionFailed(
                                    "Expected AuthChallenge".to_string(),
                                )));
                            }
                        }
                    }
                } else {
                    match parsed {
                        Messages::Send {
                            source,
                            destination,
                            payload,
                        } => {
                            if let Some(source) = source {
                                let _ = incoming_tx.send(IncomingMessage::Send {
                                    source,
                                    destination,
                                    payload,
                                });
                            }
                        }
                        Messages::RendezvousInfo(code) => {
                            let _ = incoming_tx.send(IncomingMessage::RendezvousInfo(code));
                        }
                        Messages::IdentityInfo {
                            fingerprint,
                            identity,
                        } => {
                            let _ = incoming_tx.send(IncomingMessage::IdentityInfo {
                                fingerprint,
                                identity,
                            });
                        }
                        _ => {
                            tracing::debug!("Ignoring post-auth message: {parsed:?}");
                        }
                    }
                }
            }) as Box<dyn FnMut(MessageEvent)>);
            ws.set_onmessage(Some(cb.as_ref().unchecked_ref()));
            cb.forget();
        }

        {
            let cb = Closure::wrap(Box::new(move |_: ErrorEvent| {
                tracing::error!("WebSocket error");
            }) as Box<dyn FnMut(ErrorEvent)>);
            ws.set_onerror(Some(cb.as_ref().unchecked_ref()));
            cb.forget();
        }

        {
            let cb = Closure::wrap(Box::new(move |event: CloseEvent| {
                tracing::info!(
                    "WebSocket closed: code={}, reason={}",
                    event.code(),
                    event.reason()
                );
            }) as Box<dyn FnMut(CloseEvent)>);
            ws.set_onclose(Some(cb.as_ref().unchecked_ref()));
            cb.forget();
        }

        // Wait for authentication to complete
        auth_rx
            .await
            .map_err(|_| ClientError::ConnectionFailed("Auth channel dropped".to_string()))?
            .map_err(|e| ClientError::ConnectionFailed(e.to_string()))?;

        self.ws = Some(ws);
        Ok(incoming_rx)
    }

    async fn request_rendezvous(&self) -> Result<(), ClientError> {
        self.send_json(&Messages::GetRendezvous)
    }

    async fn request_identity(&self, code: RendezvousCode) -> Result<(), ClientError> {
        self.send_json(&Messages::GetIdentity(code))
    }

    async fn send_to(
        &self,
        fingerprint: IdentityFingerprint,
        data: Vec<u8>,
    ) -> Result<(), ClientError> {
        self.send_json(&Messages::Send {
            source: None,
            destination: fingerprint,
            payload: data,
        })
    }

    async fn disconnect(&mut self) -> Result<(), ClientError> {
        if let Some(ws) = self.ws.take() {
            ws.set_onopen(None);
            ws.set_onmessage(None);
            ws.set_onerror(None);
            ws.set_onclose(None);
            let _ = ws.close();
        }
        Ok(())
    }
}

//! Browser localStorage-based storage implementations.
//!
//! Provides `IdentityProvider` and `ConnectionStore` backed by
//! the browser's `localStorage` API, plus standalone `#[wasm_bindgen]`
//! functions for listing and clearing connections from JavaScript.

use ap_client::error::ClientError;
use ap_client::{ConnectionInfo, ConnectionStore, ConnectionUpdate, IdentityProvider};
use ap_noise::{MultiDeviceTransport, PersistentTransportState};
use ap_relay_protocol::{IdentityFingerprint, IdentityKeyPair};
use async_trait::async_trait;
use serde::{Deserialize, Serialize};
use wasm_bindgen::prelude::*;
use web_sys::Storage;

use crate::types::client_error_to_js;

fn local_storage() -> Result<Storage, ClientError> {
    let window = web_sys::window()
        .ok_or_else(|| ClientError::IdentityStorageFailed("No window object".to_string()))?;
    window
        .local_storage()
        .map_err(|_| ClientError::IdentityStorageFailed("localStorage not available".to_string()))?
        .ok_or_else(|| ClientError::IdentityStorageFailed("localStorage is null".to_string()))
}

// ---------------------------------------------------------------------------
// LocalStorageIdentityProvider
// ---------------------------------------------------------------------------

/// Identity provider backed by browser localStorage.
///
/// Stores the identity keypair as base64-encoded COSE bytes under
/// the key `bw_remote_identity_{name}`.
pub struct LocalStorageIdentityProvider {
    keypair: IdentityKeyPair,
}

impl LocalStorageIdentityProvider {
    /// Load an existing identity from localStorage, or generate a new one.
    pub fn load_or_generate(name: &str) -> Result<Self, ClientError> {
        let storage = local_storage()?;
        let key = format!("bw_remote_identity_{name}");

        let keypair = match storage.get_item(&key).ok().flatten() {
            Some(b64) => {
                let cose_bytes = base64::Engine::decode(
                    &base64::engine::general_purpose::STANDARD,
                    &b64,
                )
                .map_err(|e| {
                    ClientError::IdentityStorageFailed(format!("Base64 decode error: {e}"))
                })?;
                IdentityKeyPair::from_cose(&cose_bytes).map_err(|_| {
                    ClientError::IdentityStorageFailed(
                        "Failed to parse identity from COSE".to_string(),
                    )
                })?
            }
            None => {
                let keypair = IdentityKeyPair::generate();
                let cose_bytes = keypair.to_cose();
                let b64 =
                    base64::Engine::encode(&base64::engine::general_purpose::STANDARD, &cose_bytes);
                storage.set_item(&key, &b64).map_err(|_| {
                    ClientError::IdentityStorageFailed(
                        "Failed to write identity to localStorage".to_string(),
                    )
                })?;
                keypair
            }
        };

        Ok(Self { keypair })
    }
}

#[async_trait]
impl IdentityProvider for LocalStorageIdentityProvider {
    async fn identity(&self) -> IdentityKeyPair {
        self.keypair.clone()
    }
}

// ---------------------------------------------------------------------------
// LocalStorageConnectionStore
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ConnectionRecord {
    remote_fingerprint: IdentityFingerprint,
    cached_at: u64,
    last_connected_at: u64,
    #[serde(default)]
    transport_state: Option<Vec<u8>>,
    #[serde(default)]
    name: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
struct ConnectionCacheData {
    connections: Vec<ConnectionRecord>,
}

fn record_to_info(record: &ConnectionRecord) -> ConnectionInfo {
    let transport_state = record.transport_state.as_ref().and_then(|bytes| {
        PersistentTransportState::from_bytes(bytes)
            .map(MultiDeviceTransport::from)
            .ok()
    });
    ConnectionInfo {
        fingerprint: record.remote_fingerprint,
        name: record.name.clone(),
        cached_at: record.cached_at,
        last_connected_at: record.last_connected_at,
        transport_state,
    }
}

fn info_to_record(info: &ConnectionInfo) -> Result<ConnectionRecord, ClientError> {
    let transport_bytes = match &info.transport_state {
        Some(transport) => Some(
            PersistentTransportState::from(transport)
                .to_bytes()
                .map_err(|e| {
                    ClientError::NoiseProtocol(format!(
                        "Failed to serialize transport state: {e}"
                    ))
                })?,
        ),
        None => None,
    };
    Ok(ConnectionRecord {
        remote_fingerprint: info.fingerprint,
        cached_at: info.cached_at,
        last_connected_at: info.last_connected_at,
        transport_state: transport_bytes,
        name: info.name.clone(),
    })
}

/// Connection store backed by browser localStorage.
///
/// Stores sessions as a JSON array under the key
/// `bw_remote_connections_{name}`.
pub struct LocalStorageConnectionStore {
    storage_key: String,
    data: ConnectionCacheData,
}

impl LocalStorageConnectionStore {
    /// Load existing connections from localStorage, or create empty cache.
    pub fn load_or_create(name: &str) -> Result<Self, ClientError> {
        let storage_key = format!("bw_remote_connections_{name}");

        let data = match local_storage().ok().and_then(|s| s.get_item(&storage_key).ok().flatten())
        {
            Some(json) => serde_json::from_str(&json).unwrap_or_else(|e| {
                tracing::warn!("Corrupt connection cache in localStorage, resetting: {e}");
                ConnectionCacheData { connections: Vec::new() }
            }),
            None => ConnectionCacheData {
                connections: Vec::new(),
            },
        };

        Ok(Self { storage_key, data })
    }

    /// Clear all cached connections.
    pub fn clear(&mut self) -> Result<(), ClientError> {
        self.data.connections.clear();
        self.persist()
    }

    fn persist(&self) -> Result<(), ClientError> {
        let json = serde_json::to_string(&self.data)
            .map_err(|e| ClientError::ConnectionCache(format!("Serialization failed: {e}")))?;
        let storage = local_storage().map_err(|e| {
            ClientError::ConnectionCache(format!("localStorage not available: {e}"))
        })?;
        storage.set_item(&self.storage_key, &json).map_err(|_| {
            ClientError::ConnectionCache("Failed to write to localStorage".to_string())
        })?;
        Ok(())
    }
}

#[async_trait]
impl ConnectionStore for LocalStorageConnectionStore {
    async fn get(&self, fingerprint: &IdentityFingerprint) -> Option<ConnectionInfo> {
        self.data
            .connections
            .iter()
            .find(|s| s.remote_fingerprint == *fingerprint)
            .map(record_to_info)
    }

    async fn save(&mut self, connection: ConnectionInfo) -> Result<(), ClientError> {
        let record = info_to_record(&connection)?;
        if let Some(existing) = self
            .data
            .connections
            .iter_mut()
            .find(|s| s.remote_fingerprint == connection.fingerprint)
        {
            *existing = record;
        } else {
            self.data.connections.push(record);
        }
        self.persist()
    }

    async fn update(&mut self, update: ConnectionUpdate) -> Result<(), ClientError> {
        if let Some(connection) = self
            .data
            .connections
            .iter_mut()
            .find(|s| s.remote_fingerprint == update.fingerprint)
        {
            connection.last_connected_at = update.last_connected_at;
            self.persist()
        } else {
            Err(ClientError::ConnectionCache(
                "Connection not found".to_string(),
            ))
        }
    }

    async fn list(&self) -> Vec<ConnectionInfo> {
        self.data
            .connections
            .iter()
            .map(record_to_info)
            .collect()
    }
}

// ---------------------------------------------------------------------------
// Standalone WASM functions
// ---------------------------------------------------------------------------

/// List cached connections for an identity.
///
/// @param identity_name - Name of the localStorage identity
/// @returns Array of { fingerprint, name, cachedAt, lastConnectedAt }
#[wasm_bindgen(js_name = "listConnections")]
pub async fn list_connections(identity_name: &str) -> Result<JsValue, JsValue> {
    let store =
        LocalStorageConnectionStore::load_or_create(identity_name).map_err(client_error_to_js)?;
    let connections = store.list().await;

    let arr = js_sys::Array::new();
    for conn in connections {
        let obj = js_sys::Object::new();
        let _ = js_sys::Reflect::set(
            &obj,
            &"fingerprint".into(),
            &JsValue::from_str(&hex::encode(conn.fingerprint.0)),
        );
        let _ = js_sys::Reflect::set(
            &obj,
            &"name".into(),
            &match &conn.name {
                Some(n) => JsValue::from_str(n),
                None => JsValue::NULL,
            },
        );
        let _ = js_sys::Reflect::set(
            &obj,
            &"cachedAt".into(),
            &JsValue::from_f64(conn.cached_at as f64),
        );
        let _ = js_sys::Reflect::set(
            &obj,
            &"lastConnectedAt".into(),
            &JsValue::from_f64(conn.last_connected_at as f64),
        );
        arr.push(&obj);
    }

    Ok(arr.into())
}

/// Clear all cached connections for an identity.
///
/// @param identity_name - Name of the localStorage identity
#[wasm_bindgen(js_name = "clearConnections")]
pub fn clear_connections(identity_name: &str) -> Result<(), JsValue> {
    let mut store =
        LocalStorageConnectionStore::load_or_create(identity_name).map_err(client_error_to_js)?;
    store.clear().map_err(client_error_to_js)?;
    Ok(())
}

/**
 * Bitwarden Agent Access — WASM Remote Client wrapper.
 *
 * Simple API for pairing with a trusted device and requesting credentials.
 *
 * Usage:
 *   import { createClient } from "./agent-access.js";
 *
 *   const client = await createClient("wss://ap.lesspassword.dev");
 *
 *   // Pair with a new device
 *   await client.pair("ABC-DEF-GHI");
 *
 *   // Or reconnect to a saved session
 *   await client.reconnect(fingerprint);
 *
 *   // Request a credential
 *   const cred = await client.getCredential("example.com");
 *   console.log(cred.username, cred.password);
 *
 *   // List / clear saved connections
 *   const connections = await client.listConnections();
 *   client.clearConnections();
 *
 *   // Disconnect
 *   client.disconnect();
 */

import wasmInit, {
  WasmRemoteClient,
  listConnections,
  clearConnections,
} from "../pkg/bw_remote_wasm.js";

let wasmReady = false;

async function ensureWasm() {
  if (!wasmReady) {
    await wasmInit();
    wasmReady = true;
  }
}

/** Cheap heuristic matching PskToken:[REDACTED] in Rust. */
function looksLikePskToken(s) {
  return s.length === 129 && s[64] === "_";
}

/** Extract a human-readable message from WASM/JS errors. */
function cleanError(e) {
  if (e instanceof Error) return e.message;
  const s = String(e);
  // Strip "Failed to connect to relay: Failed to create WebSocket: JsValue(...)" noise
  const jsVal = s.match(/JsValue\((?:\w+:\s*)?(.+?)(?:\s+\S+@http).*/s);
  if (jsVal) return jsVal[1].trim();
  // Strip nested "Foo: Bar: Baz" to just the innermost message
  const parts = s.split(/:\s+/);
  return parts[parts.length - 1].trim() || s;
}

/**
 * Create an Agent Access Remote Client.
 *
 * @param {string} relayUrl - WebSocket URL of the relay server
 * @param {string} [identityName="js-wasm-remote"] - Name for the localStorage identity
 * @returns {Promise<AgentAccessClient>}
 */
export async function createClient(relayUrl, identityName = "js-wasm-remote") {
  await ensureWasm();
  return new AgentAccessClient(relayUrl, identityName);
}

class AgentAccessClient {
  #inner = null;
  #relayUrl;
  #identityName;

  constructor(relayUrl, identityName) {
    if (!relayUrl || !/^wss?:\/\/.+/.test(relayUrl)) {
      throw new Error(`Invalid relay URL: "${relayUrl}" — expected ws:// or wss://`);
    }
    this.#relayUrl = relayUrl;
    this.#identityName = identityName;
  }

  /**
   * Pair with a new device using a rendezvous code or PSK token.
   * @param {string} token - Rendezvous code (e.g. "ABC-DEF-GHI") or PSK token
   * @returns {Promise<string|null>} Handshake fingerprint for rendezvous, null for PSK
   */
  async pair(token) {
    return this.#withFreshConnection((inner) =>
      looksLikePskToken(token)
        ? inner.pairWithPsk(token).then(() => null)
        : inner.pairWithHandshake(token),
    );
  }

  /**
   * Reconnect to a previously paired device.
   * @param {string} fingerprint - Hex fingerprint of the cached session
   */
  async reconnect(fingerprint) {
    return this.#withFreshConnection((inner) =>
      inner.loadCachedConnection(fingerprint),
    );
  }

  async #withFreshConnection(action) {
    this.disconnect();
    this.#inner = new WasmRemoteClient(this.#relayUrl, this.#identityName);
    try {
      await this.#inner.connect();
      return await action(this.#inner);
    } catch (e) {
      this.#inner.close();
      this.#inner = null;
      throw new Error(cleanError(e));
    }
  }

  /**
   * Request a credential by domain.
   * @param {string} domain - e.g. "example.com"
   * @returns {Promise<{username?, password?, totp?, uri?, notes?, credential_id?, domain?}>}
   */
  async getCredential(domain) {
    if (!this.#inner) throw new Error("Not connected — call pair() or reconnect() first");
    try {
      const cred = await this.#inner.requestCredential(domain);
      return cred.toJSON();
    } catch (e) {
      throw new Error(cleanError(e));
    }
  }

  /** List saved connections from localStorage. */
  async listConnections() {
    return listConnections(this.#identityName);
  }

  /** Clear all saved connections from localStorage. */
  clearConnections() {
    clearConnections(this.#identityName);
  }

  /** Disconnect and release resources. */
  disconnect() {
    if (this.#inner) {
      this.#inner.close();
      this.#inner = null;
    }
  }

}

//! Example credential provider with hardcoded credentials.
//!
//! Ships a small set of demo credentials for testing without requiring an
//! external password manager. Useful for demos, integration testing, and
//! development.

use ap_client::CredentialData;

use super::{CredentialProvider, CredentialQuery, LookupResult, ProviderStatus};

/// An in-memory credential provider with example entries for
/// example.com, google.com, and github.com.
pub struct ExampleProvider {
    credentials: Vec<CredentialData>,
}

impl ExampleProvider {
    pub fn new() -> Self {
        Self {
            credentials: vec![
                CredentialData {
                    username: Some("alice@example.com".to_string()),
                    password: Some("ex@mple-p@ssw0rd!".to_string().into()),
                    totp: None,
                    uri: Some("https://example.com/login".to_string()),
                    notes: Some("Example account for testing".to_string()),
                    credential_id: Some("cred-example-001".to_string()),
                    domain: Some("example.com".to_string()),
                },
                CredentialData {
                    username: Some("example@gmail.com".to_string()),
                    password: Some("g00gle-s3cure!".to_string().into()),
                    totp: Some("JBSWY3DPEHPK3PXP".to_string()),
                    uri: Some("https://accounts.google.com".to_string()),
                    notes: None,
                    credential_id: Some("cred-google-001".to_string()),
                    domain: Some("google.com".to_string()),
                },
                CredentialData {
                    username: Some("example-dev".to_string()),
                    password: Some("gh-t0ken-abc123!".to_string().into()),
                    totp: Some("NBSWY3DP".to_string()),
                    uri: Some("https://github.com".to_string()),
                    notes: Some("GitHub developer account".to_string()),
                    credential_id: Some("cred-github-001".to_string()),
                    domain: Some("github.com".to_string()),
                },
            ],
        }
    }
}

impl CredentialProvider for ExampleProvider {
    fn name(&self) -> &str {
        "Example"
    }

    fn status(&self) -> ProviderStatus {
        ProviderStatus::Ready {
            user_info: Some("alice (example provider)".to_string()),
        }
    }

    fn unlock(&mut self, _input: &str) -> Result<(), String> {
        Ok(())
    }

    fn lookup(&self, query: &CredentialQuery) -> LookupResult {
        let result = match query {
            CredentialQuery::Domain(domain) => {
                let domain_lower = domain.to_lowercase();
                self.credentials.iter().find(|c| {
                    c.domain
                        .as_ref()
                        .is_some_and(|d| d.to_lowercase().contains(&domain_lower))
                })
            }
            CredentialQuery::Id(id) => self
                .credentials
                .iter()
                .find(|c| c.credential_id.as_ref().is_some_and(|cid| cid == id)),
            CredentialQuery::Search(term) => {
                let term_lower = term.to_lowercase();
                self.credentials.iter().find(|c| {
                    c.domain
                        .as_ref()
                        .is_some_and(|d| d.to_lowercase().contains(&term_lower))
                        || c.username
                            .as_ref()
                            .is_some_and(|u| u.to_lowercase().contains(&term_lower))
                        || c.uri
                            .as_ref()
                            .is_some_and(|u| u.to_lowercase().contains(&term_lower))
                })
            }
        };

        match result {
            Some(cred) => LookupResult::Found(cred.clone()),
            None => LookupResult::NotFound,
        }
    }
}

