//! Custom tracing layer that routes log events into the TUI message panel.
//!
//! Instead of writing to stderr (which corrupts the ratatui alternate screen),
//! this layer sends structured log entries through an mpsc channel so they can
//! be rendered inside the TUI.

use tokio::sync::mpsc;
use tracing::field::{Field, Visit};
use tracing::{Event, Level, Subscriber};
use tracing_subscriber::Layer;
use tracing_subscriber::layer::Context;

use super::tui::{App, MessageKind};

/// Receiver half of the TUI log channel.
pub type LogReceiver = mpsc::UnboundedReceiver<TuiLogEntry>;

/// A single log entry destined for the TUI message panel.
pub struct TuiLogEntry {
    pub level: Level,
    pub message: String,
    /// Last segment of the tracing target (e.g. `"remote_client"` from
    /// `"ap_client::clients::remote_client"`).
    pub short_target: String,
}

/// A [`tracing_subscriber::Layer`] that forwards log events to a channel.
pub struct TuiLayer {
    tx: mpsc::UnboundedSender<TuiLogEntry>,
}

impl TuiLayer {
    /// Create a new TUI layer and the receiver that the TUI event loop should poll.
    pub fn new() -> (Self, LogReceiver) {
        let (tx, rx) = mpsc::unbounded_channel();
        (Self { tx }, rx)
    }
}

/// Visitor that extracts the `message` field from a tracing event.
struct MessageVisitor {
    message: String,
}

impl MessageVisitor {
    fn new() -> Self {
        Self {
            message: String::new(),
        }
    }
}

impl Visit for MessageVisitor {
    fn record_debug(&mut self, field: &Field, value: &dyn std::fmt::Debug) {
        if field.name() == "message" {
            use std::fmt::Write;
            self.message.clear();
            let _ = write!(self.message, "{value:?}");
        }
    }

    fn record_str(&mut self, field: &Field, value: &str) {
        if field.name() == "message" {
            self.message = value.to_string();
        }
    }
}

impl<S: Subscriber> Layer<S> for TuiLayer {
    fn on_event(&self, event: &Event<'_>, _ctx: Context<'_, S>) {
        let mut visitor = MessageVisitor::new();
        event.record(&mut visitor);

        let target = event.metadata().target();
        let short_target = target.rsplit("::").next().unwrap_or(target).to_string();

        let entry = TuiLogEntry {
            level: *event.metadata().level(),
            message: visitor.message,
            short_target,
        };

        // Best-effort send — if the receiver is gone, just drop the entry.
        let _ = self.tx.send(entry);
    }
}

/// Push a [`TuiLogEntry`] into the TUI message panel with appropriate styling.
pub fn push_log_entry(app: &mut App, entry: TuiLogEntry) {
    let kind = match entry.level {
        Level::ERROR | Level::WARN => MessageKind::Error,
        _ => MessageKind::Info,
    };
    app.push_msg(kind, format!("[{}] {}", entry.short_target, entry.message));
}

use std::fs;
use std::path::{Path, PathBuf};

use ap_client::{ClientError, ConnectionInfo, ConnectionStore, ConnectionUpdate};
use ap_noise::{MultiDeviceTransport, PersistentTransportState};
use ap_relay_protocol::IdentityFingerprint;
use async_trait::async_trait;
use serde::{Deserialize, Serialize};
use tracing::debug;

/// Connection record stored in cache (serde representation).
///
/// Transport state is stored as CBOR bytes for serialization.
#[derive(Debug, Clone, Serialize, Deserialize)]
struct ConnectionRecord {
    remote_fingerprint: IdentityFingerprint,
    cached_at: u64,
    last_connected_at: u64,
    #[serde(default)]
    transport_state: Option<Vec<u8>>,
    #[serde(default)]
    name: Option<String>,
}

/// Cache data structure
#[derive(Debug, Clone, Serialize, Deserialize)]
struct ConnectionCacheData {
    connections: Vec<ConnectionRecord>,
}

/// Convert a `ConnectionRecord` to a `ConnectionInfo`, deserializing transport state.
fn record_to_info(record: &ConnectionRecord) -> Result<ConnectionInfo, ClientError> {
    let transport_state = match &record.transport_state {
        Some(bytes) => {
            Some(PersistentTransportState::from_bytes(bytes).map(MultiDeviceTransport::from)?)
        }
        None => None,
    };

    Ok(ConnectionInfo {
        fingerprint: record.remote_fingerprint,
        name: record.name.clone(),
        cached_at: record.cached_at,
        last_connected_at: record.last_connected_at,
        transport_state,
    })
}

/// Convert a `ConnectionInfo` to a `ConnectionRecord`, serializing transport state.
fn info_to_record(info: &ConnectionInfo) -> Result<ConnectionRecord, ClientError> {
    let transport_bytes = match &info.transport_state {
        Some(transport) => Some(
            PersistentTransportState::from(transport)
                .to_bytes()
                .map_err(|e| {
                    ClientError::NoiseProtocol(format!("Failed to serialize transport state: {e}"))
                })?,
        ),
        None => None,
    };

    Ok(ConnectionRecord {
        remote_fingerprint: info.fingerprint,
        cached_at: info.cached_at,
        last_connected_at: info.last_connected_at,
        transport_state: transport_bytes,
        name: info.name.clone(),
    })
}

/// File-based connection cache implementation
///
/// Stores connections in a JSON file at ~/.access-protocol/connection_cache_{name}.json
pub struct FileConnectionCache {
    cache_path: PathBuf,
    data: ConnectionCacheData,
}

#[async_trait]
impl ConnectionStore for FileConnectionCache {
    async fn get(&self, fingerprint: &IdentityFingerprint) -> Option<ConnectionInfo> {
        self.data
            .connections
            .iter()
            .find(|s| s.remote_fingerprint == *fingerprint)
            .and_then(|record| match record_to_info(record) {
                Ok(info) => Some(info),
                Err(e) => {
                    debug!(
                        "Failed to deserialize connection for {:?}: {}",
                        fingerprint, e
                    );
                    None
                }
            })
    }

    async fn save(&mut self, connection: ConnectionInfo) -> Result<(), ClientError> {
        let record = info_to_record(&connection)?;

        if let Some(existing) = self
            .data
            .connections
            .iter_mut()
            .find(|s| s.remote_fingerprint == connection.fingerprint)
        {
            *existing = record;
            debug!("Updated existing connection cache entry");
        } else {
            self.data.connections.push(record);
            debug!("Added new connection cache entry");
        }

        self.persist()?;
        Ok(())
    }

    async fn update(&mut self, update: ConnectionUpdate) -> Result<(), ClientError> {
        if let Some(connection) = self
            .data
            .connections
            .iter_mut()
            .find(|s| s.remote_fingerprint == update.fingerprint)
        {
            connection.last_connected_at = update.last_connected_at;
            self.persist()?;
            debug!("Updated last_connected_at for connection");
            Ok(())
        } else {
            Err(ClientError::ConnectionCache(
                "Connection not found".to_string(),
            ))
        }
    }

    async fn list(&self) -> Vec<ConnectionInfo> {
        self.data
            .connections
            .iter()
            .filter_map(|record| match record_to_info(record) {
                Ok(info) => Some(info),
                Err(e) => {
                    debug!("Failed to deserialize connection: {}", e);
                    None
                }
            })
            .collect()
    }
}

impl FileConnectionCache {
    /// Clear all cached connections.
    pub async fn clear(&mut self) -> Result<(), ClientError> {
        self.data.connections.clear();
        self.persist()?;
        debug!("Cleared all connection cache entries");
        Ok(())
    }

    /// Load or create connection cache
    pub fn load_or_create(cache_name: &str) -> Result<Self, ClientError> {
        let cache_path = Self::default_cache_path(cache_name)?;

        let data = if cache_path.exists() {
            debug!("Loading connection cache from {:?}", cache_path);
            Self::load_from_file(&cache_path)?
        } else {
            debug!("Creating new connection cache");
            ConnectionCacheData {
                connections: Vec::new(),
            }
        };

        Ok(Self { cache_path, data })
    }

    /// Save cache to disk
    fn persist(&self) -> Result<(), ClientError> {
        let json = serde_json::to_string_pretty(&self.data)
            .map_err(|e| ClientError::ConnectionCache(format!("Serialization failed: {e}")))?;

        fs::write(&self.cache_path, json).map_err(|e| {
            ClientError::ConnectionCache(format!("Failed to write cache file: {e}"))
        })?;

        debug!("Saved connection cache");
        Ok(())
    }

    /// Get default cache path (~/.access-protocol/connection_cache_{cache_name}.json)
    fn default_cache_path(cache_name: &str) -> Result<PathBuf, ClientError> {
        let home_dir = dirs::home_dir().ok_or_else(|| {
            ClientError::ConnectionCache("Could not find home directory".to_string())
        })?;

        let ap_dir = home_dir.join(".access-protocol");
        if !ap_dir.exists() {
            fs::create_dir_all(&ap_dir).map_err(|e| {
                ClientError::ConnectionCache(format!(
                    "Failed to create .access-protocol directory: {e}"
                ))
            })?;
        }

        Ok(ap_dir.join(format!("connection_cache_{cache_name}.json")))
    }

    /// Load cache from file
    fn load_from_file(path: &Path) -> Result<ConnectionCacheData, ClientError> {
        let contents = fs::read_to_string(path)
            .map_err(|e| ClientError::ConnectionCache(format!("Failed to read cache file: {e}")))?;

        let data: ConnectionCacheData = serde_json::from_str(&contents).map_err(|e| {
            ClientError::ConnectionCache(format!("Failed to parse cache file: {e}"))
        })?;

        debug!("Loaded {} connection(s) from cache", data.connections.len());
        Ok(data)
    }
}

mod connection_storage;
mod identity_storage;
mod psk_storage;

pub use connection_storage::FileConnectionCache;
pub use identity_storage::FileIdentityStorage;
pub use psk_storage::FilePskStore;

use ap_relay_protocol::{Challenge, IdentityFingerprint, Messages, RelayError, RendezvousCode};

use crate::{connection::AuthenticatedConnection, server::relay_server::ServerState};

fn ws_err(e: tokio_tungstenite::tungstenite::Error) -> RelayError {
    RelayError::WebSocket(e.to_string())
}
use futures_util::{SinkExt, StreamExt};
use std::sync::Arc;
use std::time::{Duration, SystemTime};

/// Maximum time the server waits without receiving any message (including
/// client pings) before considering the connection dead and closing it.
const CLIENT_INACTIVITY_TIMEOUT: Duration = Duration::from_secs(120);
use tokio::net::TcpStream;
use tokio::sync::mpsc;
use tokio_tungstenite::{WebSocketStream, tungstenite::Message};

pub struct ConnectionHandler {
    conn_id: u64,
    state: Arc<ServerState>,
    ws_stream: WebSocketStream<TcpStream>,
}

impl ConnectionHandler {
    pub fn new(
        conn_id: u64,
        state: Arc<ServerState>,
        ws_stream: WebSocketStream<TcpStream>,
    ) -> Self {
        Self {
            conn_id,
            state,
            ws_stream,
        }
    }

    pub async fn handle(self) -> Result<(), RelayError> {
        let conn_id = self.conn_id;
        let state = self.state;

        let (mut ws_write, mut ws_read) = self.ws_stream.split();
        let (tx, mut rx) = mpsc::unbounded_channel::<Message>();

        let write_task = tokio::spawn(async move {
            while let Some(msg) = rx.recv().await {
                if let Err(e) = ws_write.send(msg).await {
                    tracing::error!("Failed to send message: {}", e);
                    break;
                }
            }
        });

        let challenge = Challenge::new();
        let challenge_msg = serde_json::to_string(&Messages::AuthChallenge(challenge.clone()))?;
        if tx.send(Message::Text(challenge_msg)).is_err() {
            return Err(RelayError::ConnectionClosed);
        }

        tracing::debug!("Connection #{}: Sent auth challenge", conn_id);

        // Wait for auth response
        let auth_response = match tokio::time::timeout(Duration::from_secs(5), ws_read.next()).await
        {
            Ok(Some(Ok(Message::Text(text)))) => text,
            Ok(Some(Ok(_))) => {
                return Err(RelayError::InvalidMessage(
                    "Expected text message for auth".to_string(),
                ));
            }
            Ok(Some(Err(e))) => return Err(ws_err(e)),
            Ok(None) => return Err(RelayError::ConnectionClosed),
            Err(_) => return Err(RelayError::AuthenticationTimeout),
        };

        let (identity, fingerprint) = match serde_json::from_str::<Messages>(&auth_response)? {
            Messages::AuthResponse(identity, response) => {
                if !response.verify(&challenge, &identity) {
                    return Err(RelayError::AuthenticationFailed(
                        "Invalid signature".to_string(),
                    ));
                }
                let fingerprint = identity.fingerprint();
                tracing::info!(
                    "Connection #{}: Authenticated as {:?}",
                    conn_id,
                    fingerprint
                );
                (identity, fingerprint)
            }
            _ => {
                return Err(RelayError::AuthenticationFailed(
                    "Expected AuthResponse".to_string(),
                ));
            }
        };

        let authenticated_conn = Arc::new(AuthenticatedConnection {
            conn_id,
            fingerprint,
            identity,
            tx: tx.clone(),
            connected_at: SystemTime::now(),
        });

        {
            let mut connections = state.connections.write().await;
            connections
                .entry(fingerprint)
                .or_insert_with(Vec::new)
                .push(Arc::clone(&authenticated_conn));
        }

        tracing::info!("Connection #{}: Added to connection map", conn_id);

        let result =
            Self::handle_authenticated_messages(&state, &mut ws_read, fingerprint, conn_id).await;

        {
            let mut connections = state.connections.write().await;
            if let Some(conns) = connections.get_mut(&fingerprint) {
                conns.retain(|c| c.conn_id != conn_id);
                if conns.is_empty() {
                    connections.remove(&fingerprint);
                }
            }
        }

        tracing::info!("Connection #{}: Removed from connection map", conn_id);

        drop(tx);
        let _ = write_task.await;

        result
    }

    async fn handle_authenticated_messages(
        state: &Arc<ServerState>,
        ws_read: &mut futures_util::stream::SplitStream<WebSocketStream<TcpStream>>,
        fingerprint: IdentityFingerprint,
        conn_id: u64,
    ) -> Result<(), RelayError> {
        let inactivity_deadline = tokio::time::sleep(CLIENT_INACTIVITY_TIMEOUT);
        tokio::pin!(inactivity_deadline);

        loop {
            let msg = tokio::select! {
                msg_result = ws_read.next() => {
                    match msg_result {
                        Some(Ok(Message::Text(text))) => {
                            // Reset inactivity timer only on real protocol messages
                            inactivity_deadline
                                .as_mut()
                                .reset(tokio::time::Instant::now() + CLIENT_INACTIVITY_TIMEOUT);
                            text
                        }
                        Some(Ok(Message::Close(_))) => {
                            tracing::info!("Connection #{}: Client closed connection", conn_id);
                            return Ok(());
                        }
                        Some(Ok(_)) => {
                            // Pings/pongs/binary frames also indicate the client is alive
                            inactivity_deadline
                                .as_mut()
                                .reset(tokio::time::Instant::now() + CLIENT_INACTIVITY_TIMEOUT);
                            continue;
                        }
                        Some(Err(e)) => return Err(ws_err(e)),
                        None => return Ok(()),
                    }
                }
                _ = &mut inactivity_deadline => {
                    tracing::info!(
                        "Connection #{}: Client inactive for {}s, closing",
                        conn_id,
                        CLIENT_INACTIVITY_TIMEOUT.as_secs()
                    );
                    return Ok(());
                }
            };

            let parsed_msg: Messages = match serde_json::from_str(&msg) {
                Ok(m) => m,
                Err(e) => {
                    tracing::warn!("Connection #{}: Failed to parse message: {}", conn_id, e);
                    continue;
                }
            };

            match parsed_msg {
                Messages::AuthChallenge(_) | Messages::AuthResponse(_, _) => {
                    tracing::warn!(
                        "Connection #{}: Received auth message after authentication",
                        conn_id
                    );
                }
                Messages::GetRendezvous => {
                    let code = RendezvousCode::new();
                    tracing::info!(
                        "Connection #{}: Generated rendezvous code: {}",
                        conn_id,
                        code.as_str()
                    );

                    // Store mapping in rendezvous_map
                    {
                        use crate::server::relay_server::RendezvousEntry;
                        let entry = RendezvousEntry {
                            fingerprint,
                            created_at: SystemTime::now(),
                            used: false,
                        };
                        state
                            .rendezvous_map
                            .write()
                            .await
                            .insert(code.as_str().to_string(), entry);
                    }

                    let response = serde_json::to_string(&Messages::RendezvousInfo(code))?;
                    let connections = state.connections.read().await;
                    if let Some(conns) = connections.get(&fingerprint) {
                        for conn in conns.iter() {
                            let _ = conn.tx.send(Message::Text(response.clone()));
                        }
                    }
                }
                Messages::Send {
                    source: _,
                    destination,
                    payload,
                } => {
                    // Use authenticated fingerprint as source (client doesn't provide it)
                    let source = fingerprint;

                    // Route message to all connections with destination fingerprint
                    let dest_conns = {
                        let connections = state.connections.read().await;
                        connections.get(&destination).cloned()
                    };

                    match dest_conns {
                        Some(conns) if !conns.is_empty() => {
                            let forward_msg = serde_json::to_string(&Messages::Send {
                                source: Some(source),
                                destination,
                                payload,
                            })?;
                            for conn in conns.iter() {
                                if conn.tx.send(Message::Text(forward_msg.clone())).is_err() {
                                    tracing::error!(
                                        "Connection #{}: Failed to deliver to conn #{}",
                                        conn_id,
                                        conn.conn_id
                                    );
                                }
                            }
                            tracing::debug!(
                                "Connection #{}: Broadcast message from {:?} to {:?} ({} recipients)",
                                conn_id,
                                source,
                                destination,
                                conns.len()
                            );
                        }
                        _ => {
                            tracing::warn!(
                                "Connection #{}: Destination not found: {:?}",
                                conn_id,
                                destination
                            );
                        }
                    }
                }
                Messages::RendezvousInfo(_) => {
                    tracing::warn!(
                        "Connection #{}: Received RendezvousInfo (server-only message)",
                        conn_id
                    );
                }
                Messages::IdentityInfo { .. } => {
                    tracing::warn!(
                        "Connection #{}: Received IdentityInfo (server-only message)",
                        conn_id
                    );
                }
                Messages::GetIdentity(code) => {
                    // Lookup and validate rendezvous code
                    let target_fingerprint = {
                        let mut rendezvous_map = state.rendezvous_map.write().await;

                        match rendezvous_map.get_mut(code.as_str()) {
                            Some(entry) => {
                                // Check expiration (5 minutes)
                                let elapsed = SystemTime::now()
                                    .duration_since(entry.created_at)
                                    .unwrap_or_default();

                                if elapsed.as_secs() > 300 {
                                    tracing::warn!(
                                        "Connection #{}: Rendezvous code expired: {}",
                                        conn_id,
                                        code.as_str()
                                    );
                                    rendezvous_map.remove(code.as_str());
                                    None
                                } else if entry.used {
                                    tracing::warn!(
                                        "Connection #{}: Rendezvous code already used: {}",
                                        conn_id,
                                        code.as_str()
                                    );
                                    None
                                } else {
                                    // Mark as used
                                    entry.used = true;
                                    Some(entry.fingerprint)
                                }
                            }
                            None => {
                                tracing::warn!(
                                    "Connection #{}: Unknown rendezvous code: {}",
                                    conn_id,
                                    code.as_str()
                                );
                                None
                            }
                        }
                    };

                    // Lookup target connection and send IdentityInfo
                    if let Some(target_fp) = target_fingerprint {
                        let connections = state.connections.read().await;
                        if let Some(target_conns) = connections.get(&target_fp) {
                            // Use the first connection's identity (all connections with same fingerprint have same identity)
                            if let Some(target_conn) = target_conns.first() {
                                let response_msg = Messages::IdentityInfo {
                                    fingerprint: target_fp,
                                    identity: target_conn.identity.clone(),
                                };
                                let response = serde_json::to_string(&response_msg)?;

                                // Send to all requester connections
                                if let Some(requester_conns) = connections.get(&fingerprint) {
                                    for requester_conn in requester_conns.iter() {
                                        if requester_conn
                                            .tx
                                            .send(Message::Text(response.clone()))
                                            .is_err()
                                        {
                                            tracing::error!(
                                                "Connection #{}: Failed to send IdentityInfo response to conn #{}",
                                                conn_id,
                                                requester_conn.conn_id
                                            );
                                        }
                                    }
                                }
                            }
                        } else {
                            tracing::warn!(
                                "Connection #{}: Target disconnected for rendezvous code: {}",
                                conn_id,
                                code.as_str()
                            );
                        }
                    }
                }
            }
        }
    }
}

//! Relay server implementation.
//!
//! This module provides the server-side implementation of the ap-relay server.
//! The server can be run standalone using the binary, or embedded in custom applications.
//!
//! # Running as a Binary
//!
//! The simplest way to run the relay server:
//!
//! ```bash
//! cargo run --bin ap-relay
//! ```
//!
//! # Embedding in Your Application
//!
//! You can embed the relay server in your own application:
//!
//! ```no_run
//! use ap_relay::server::RelayServer;
//! use std::net::SocketAddr;
//!
//! # async fn example() -> Result<(), Box<dyn std::error::Error>> {
//! let addr: SocketAddr = "127.0.0.1:8080".parse()?;
//! let server = RelayServer::new(addr);
//!
//! // Run the server (blocks until shutdown)
//! server.run().await?;
//! # Ok(())
//! # }
//! ```
//!
//! # Server Responsibilities
//!
//! The relay server:
//! - Accepts WebSocket connections from clients
//! - Authenticates clients using MlDsa65 challenge-response
//! - Manages rendezvous codes for peer discovery
//! - Routes messages between authenticated clients
//! - Cleans up expired rendezvous codes automatically
//!
//! # Security Considerations
//!
//! The server operates as a zero-knowledge relay:
//! - Verifies client identities via cryptographic signatures
//! - Routes messages based on fingerprints
//! - Does not decrypt or inspect message payloads
//! - Sees metadata: source, destination, timing, message size

mod handler;
mod relay_server;

pub use relay_server::RelayServer;

use ap_relay_protocol::{IdentityFingerprint, RelayError};

use crate::connection::AuthenticatedConnection;
use crate::server::handler::ConnectionHandler;
use std::collections::HashMap;
use std::net::SocketAddr;
use std::sync::Arc;
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::SystemTime;
use tokio::net::TcpListener;
use tokio::sync::RwLock;
use tokio_tungstenite::accept_async;

pub struct RendezvousEntry {
    pub fingerprint: IdentityFingerprint,
    pub created_at: SystemTime,
    pub used: bool,
}

pub struct ServerState {
    pub connections: Arc<RwLock<HashMap<IdentityFingerprint, Vec<Arc<AuthenticatedConnection>>>>>,
    pub rendezvous_map: Arc<RwLock<HashMap<String, RendezvousEntry>>>,
}

impl Default for ServerState {
    fn default() -> Self {
        Self::new()
    }
}

impl ServerState {
    pub fn new() -> Self {
        Self {
            connections: Arc::new(RwLock::new(HashMap::new())),
            rendezvous_map: Arc::new(RwLock::new(HashMap::new())),
        }
    }
}

/// The relay server that accepts client connections and relays messages.
///
/// This server handles:
/// - Client authentication using MlDsa65 challenge-response
/// - Rendezvous code generation and lookup
/// - Message routing between authenticated clients
/// - Automatic cleanup of expired rendezvous codes
///
/// # Examples
///
/// Run a standalone server:
///
/// ```no_run
/// use ap_relay::server::RelayServer;
/// use std::net::SocketAddr;
///
/// # async fn example() -> Result<(), Box<dyn std::error::Error>> {
/// let addr: SocketAddr = "127.0.0.1:8080".parse()?;
/// let server = RelayServer::new(addr);
///
/// println!("Starting relay server on {}", addr);
/// server.run().await?;
/// # Ok(())
/// # }
/// ```
///
/// Embed in an application with cancellation:
///
/// ```no_run
/// use ap_relay::server::RelayServer;
/// use std::net::SocketAddr;
/// use tokio::signal;
///
/// # async fn example() -> Result<(), Box<dyn std::error::Error>> {
/// let addr: SocketAddr = "127.0.0.1:8080".parse()?;
/// let server = RelayServer::new(addr);
///
/// tokio::select! {
///     result = server.run() => {
///         result?;
///     }
///     _ = signal::ctrl_c() => {
///         println!("Shutting down...");
///     }
/// }
/// # Ok(())
/// # }
/// ```
pub struct RelayServer {
    bind_addr: SocketAddr,
    state: Arc<ServerState>,
    conn_counter: AtomicU64,
}

impl RelayServer {
    /// Create a new relay server that will listen on the given address.
    ///
    /// This does not start the server - call [`run()`](RelayServer::run) to begin
    /// accepting connections.
    ///
    /// # Examples
    ///
    /// ```
    /// use ap_relay::server::RelayServer;
    /// use std::net::SocketAddr;
    ///
    /// let addr: SocketAddr = "127.0.0.1:8080".parse().unwrap();
    /// let server = RelayServer::new(addr);
    /// ```
    pub fn new(bind_addr: SocketAddr) -> Self {
        Self {
            bind_addr,
            state: Arc::new(ServerState::new()),
            conn_counter: AtomicU64::new(0),
        }
    }

    /// Run the relay server, accepting and handling connections.
    ///
    /// This method:
    /// 1. Binds to the configured address
    /// 2. Spawns a background task to clean up expired rendezvous codes
    /// 3. Accepts incoming WebSocket connections
    /// 4. Spawns a handler task for each connection
    /// 5. Runs indefinitely until an error occurs or cancelled
    ///
    /// # Cancellation
    ///
    /// Use `tokio::select!` or similar to cancel the server:
    ///
    /// ```no_run
    /// use ap_relay::server::RelayServer;
    /// use std::net::SocketAddr;
    /// use tokio::signal;
    ///
    /// # async fn example() -> Result<(), Box<dyn std::error::Error>> {
    /// let addr: SocketAddr = "127.0.0.1:8080".parse()?;
    /// let server = RelayServer::new(addr);
    ///
    /// tokio::select! {
    ///     result = server.run() => result?,
    ///     _ = signal::ctrl_c() => {
    ///         println!("Shutting down gracefully");
    ///     }
    /// }
    /// # Ok(())
    /// # }
    /// ```
    ///
    /// # Errors
    ///
    /// Returns an error if:
    /// - The bind address is already in use
    /// - The address is invalid or cannot be bound
    /// - A network error occurs
    ///
    /// # Examples
    ///
    /// ```no_run
    /// use ap_relay::server::RelayServer;
    /// use std::net::SocketAddr;
    ///
    /// # async fn example() -> Result<(), Box<dyn std::error::Error>> {
    /// let addr: SocketAddr = "127.0.0.1:8080".parse()?;
    /// let server = RelayServer::new(addr);
    /// server.run().await?;
    /// # Ok(())
    /// # }
    /// ```
    pub async fn run(&self) -> Result<(), RelayError> {
        let listener = TcpListener::bind(self.bind_addr).await?;
        tracing::info!("Relay server listening on {}", self.bind_addr);
        self.run_with_listener(listener).await
    }

    /// Run the relay server using an already-bound `TcpListener`.
    ///
    /// This is useful in tests to avoid the race condition of binding a port,
    /// dropping the listener, and re-binding.
    pub async fn run_with_listener(&self, listener: TcpListener) -> Result<(), RelayError> {
        // Spawn background cleanup task for expired rendezvous codes
        let cleanup_state = Arc::clone(&self.state);
        tokio::spawn(async move {
            loop {
                tokio::time::sleep(tokio::time::Duration::from_secs(60)).await;

                let mut rendezvous_map = cleanup_state.rendezvous_map.write().await;
                let now = SystemTime::now();
                let mut expired_codes = Vec::new();

                for (code, entry) in rendezvous_map.iter() {
                    let elapsed = now.duration_since(entry.created_at).unwrap_or_default();

                    if elapsed.as_secs() > 300 {
                        expired_codes.push(code.clone());
                    }
                }

                for code in expired_codes {
                    rendezvous_map.remove(&code);
                    tracing::debug!("Cleaned up expired rendezvous code: {}", code);
                }
            }
        });

        loop {
            let (stream, peer_addr) = listener.accept().await?;
            let conn_id = self.conn_counter.fetch_add(1, Ordering::SeqCst);

            tracing::info!("New connection #{} from {}", conn_id, peer_addr);

            let state = Arc::clone(&self.state);

            tokio::spawn(async move {
                match accept_async(stream).await {
                    Ok(ws_stream) => {
                        let handler = ConnectionHandler::new(conn_id, state, ws_stream);
                        if let Err(e) = handler.handle().await {
                            tracing::error!("Connection #{} error: {}", conn_id, e);
                        }
                    }
                    Err(e) => {
                        tracing::error!(
                            "Failed to accept WebSocket connection #{}: {}",
                            conn_id,
                            e
                        );
                    }
                }
            });
        }
    }
}
